ALTER TABLE "operations_promotion_daily_metric" ADD CONSTRAINT "operations_promotion_daily_decision_check" CHECK ("operations_promotion_daily_metric"."review_decision" IN ('test_continue','restart_testing','wait_continue','test_discarded','start_scaling','scaling_continue','formal_discarded','ended','test_pause','test_pending','scaling_pause'));--> statement-breakpoint
ALTER TABLE "operations_promotion_stage" ADD CONSTRAINT "operations_promotion_stage_outcome_check" CHECK ("operations_promotion_stage"."outcome" IS NULL OR "operations_promotion_stage"."outcome" IN ('continued', 'paused', 'restarted', 'start_scaling', 'test_discarded', 'scaling_continued', 'ended', 'formal_discarded'));--> statement-breakpoint
ALTER TABLE "operations_promotion_wait_range" ADD CONSTRAINT "operations_promotion_wait_decision_check" CHECK (("operations_promotion_wait_range"."next_decision" IS NULL AND "operations_promotion_wait_range"."next_effective_on" IS NULL) OR ("operations_promotion_wait_range"."next_decision" IS NOT NULL AND "operations_promotion_wait_range"."next_effective_on" IS NOT NULL AND (("operations_promotion_wait_range"."stage_type" = 'testing' AND "operations_promotion_wait_range"."next_decision" IN ('test_continue','restart_testing','start_scaling','test_discarded')) OR ("operations_promotion_wait_range"."stage_type" = 'scaling' AND "operations_promotion_wait_range"."next_decision" IN ('scaling_continue','formal_discarded','ended')))));